          try: R`اعمل route تجربة بيرمي error، شغّله مرة، وشوف الـ issue في Sentry ومعاه environment و release. بعدين امسح الـ route. وظبط alert يوصلك على Telegram أو الإيميل لما يظهر issue جديد في production.`,
